-- Seed method and brief, cautious history for current cocktail/mocktail technical sheets.
update public.product_recipes as recipe
set method = source.method, history = source.history
from (values
  ('Aperol Spritz','Enche um copo de vinho com gelo. Mede e verte o espumante e o Aperol, acrescenta a água com gás e mexe suavemente uma vez. Serve de imediato.','A família Spritz está ligada ao nordeste de Itália e à tradição de alongar vinho com água com gás. A versão com Aperol tornou-se uma das mais conhecidas no século XX.'),
  ('Blue Lagoon','Enche um shaker com gelo, junta vodka e curaçao azul e agita. Verte para um copo alto com gelo fresco, completa com limonada/Sprite e mexe suavemente.','É um cocktail azul de vodka e curaçao que se difundiu internacionalmente no século XX. As versões sobre o local e o autor da criação não são consensuais.'),
  ('Caipi Maracujá','Coloca a lima e o açúcar no copo e macera suavemente. Junta a polpa de maracujá e a cachaça, enche com gelo e mexe para integrar.','Variação contemporânea da caipirinha brasileira: mantém a combinação de cachaça e lima e acrescenta maracujá. A criação específica desta versão não tem uma origem histórica única documentada.'),
  ('Caipirinha','Corta a lima em pedaços e coloca-a no copo com o açúcar. Macera suavemente para libertar o sumo sem esmagar demasiado a casca. Junta a cachaça, enche com gelo e mexe.','É um clássico brasileiro associado à cachaça e à lima. A sua origem é contada através de várias versões e não há uma única narrativa consensual.'),
  ('Cocktail Preguiça','A ficha indica gin, vodka, rum e um componente “unicórnio” por definir. Não preparar até a Gerência confirmar o componente, as medidas e a sequência da receita da casa.','Cocktail de assinatura do Preguiça Café & Cocktails. A história e a receita completa da casa devem ser confirmadas pela Gerência; não foi indicada uma origem externa.'),
  ('Expresso Martini','Enche o shaker com gelo. Junta vodka, licor de café, um espresso acabado de extrair e xarope. Agita vigorosamente até ficar bem frio e com espuma. Coa para um copo de cocktail frio.','É geralmente atribuído ao bartender londrino Dick Bradsell, que criou uma bebida de vodka e café na década de 1980. A história popular da cliente que pediu algo para a despertar é frequentemente repetida, mas tem versões diferentes.'),
  ('Ginger Mint','Coloca o gengibre, a lima e a hortelã no copo e macera suavemente. Junta gelo, completa com ginger ale e mexe.','Mocktail contemporâneo que combina gengibre, citrinos e hortelã. A ficha não indica uma origem histórica específica.'),
  ('Godfather','Coloca o whisky e o amaretto num copo baixo com gelo. Mexe suavemente até arrefecer e serve no mesmo copo.','A mistura de whisky e amaretto ganhou popularidade na segunda metade do século XX. A associação do nome ao filme The Godfather é comum, embora a autoria exata não esteja estabelecida.'),
  ('Hurricane','Junta rum, sumos de laranja e ananás, maracujá e grenadine num shaker com gelo. Agita, verte para um copo alto com gelo fresco e serve.','O Hurricane ficou associado aos bares de Nova Orleães e à casa Pat O’Brien’s, em meados do século XX. A história exata da sua criação é contada em diferentes versões.'),
  ('Long Island Ice Tea','Enche um copo alto com gelo. Mede e junta gin, vodka, rum, tequila e triple sec. Completa com cola e mexe suavemente, sem agitar.','O Long Island Iced Tea tornou-se conhecido nos Estados Unidos na década de 1970. Existem relatos concorrentes sobre a sua origem e autoria.'),
  ('Margarita','Coloca tequila, triple sec e sumo de lima num shaker com gelo. Agita até arrefecer e coa para um copo frio; serve conforme a apresentação definida pela casa.','A Margarita é um clássico de tequila e citrinos associado ao México e aos Estados Unidos. As várias histórias de criação situam-na no século XX, mas nenhuma autoria é consensual.'),
  ('Mexican Mule','Enche um copo com gelo. Junta tequila, sumo de lima e xarope de agave. Completa com ginger ale e mexe suavemente.','É uma variação contemporânea do Moscow Mule, que troca a vodka por tequila e mantém a combinação de lima e bebida de gengibre. Não existe uma data única de criação amplamente confirmada.'),
  ('Mojito','Coloca a lima e o açúcar no copo e macera suavemente. Junta a hortelã e pressiona-a de leve, sem a triturar. Acrescenta o rum, enche com gelo e completa com água com gás. Mexe suavemente.','O Mojito está profundamente ligado à cultura de bar cubana. A sua história tem várias versões; a bebida tornou-se conhecida internacionalmente durante o século XX.'),
  ('Mojito Melancia','Coloca a melancia, a lima e o açúcar no copo e macera. Junta a hortelã e pressiona-a suavemente. Acrescenta o rum, enche com gelo, completa com água com gás e mexe.','Variação moderna do Mojito que acrescenta melancia à combinação cubana de rum, lima, açúcar e hortelã. A versão específica não tem uma origem histórica única documentada.'),
  ('Mongolia M.F.','A ficha não identifica as quantidades de sumos/xaropes nem a sequência completa. Confirmar a receita, medidas, copo e apresentação com a Gerência antes de preparar.','Nome e receita própria do Preguiça Café & Cocktails. A história desta criação não foi fornecida; deve ser confirmada pela Gerência.'),
  ('Moscow Mule','Enche um copo alto ou caneca com gelo. Junta vodka e lima, completa com ginger ale e mexe suavemente.','Popularizou-se nos Estados Unidos na década de 1940, quando bares começaram a servir vodka com bebida de gengibre e lima. A caneca de cobre ficou associada à apresentação, mas deve seguir-se o copo da casa.'),
  ('Negroni','Mede partes iguais de gin, Campari e vermute rosso para um copo baixo com gelo. Mexe até arrefecer e serve no mesmo copo.','A narrativa tradicional situa a criação em Florença, em 1919, quando o conde Camillo Negroni terá pedido gin no lugar da soda do Americano. A história é celebrada em Florença, embora seja transmitida como uma tradição.'),
  ('Old Fashioned','Coloca o açúcar e as gotas de Angostura num copo baixo com um pouco de água e mexe até dissolver. Junta o bourbon e um cubo grande de gelo; mexe suavemente.','A definição impressa de “cocktail” publicada em 1806 descrevia uma mistura de bebida espirituosa, açúcar, água e bitters. O Old Fashioned preserva essa estrutura simples; o nome consolidou-se mais tarde.'),
  ('Piña Colada','Junta o rum, o sumo de ananás e o coco no liquidificador com gelo picado. Tritura até ficar homogéneo e serve de imediato.','A Piña Colada está ligada a Porto Rico e a San Juan. Uma história atribui a receita ao Caribe Hilton em 1954; existem outras versões sobre a sua origem.'),
  ('Preguiça Mule','Enche um copo com gelo. Junta gin, pepino e lima, completa com ginger ale e mexe suavemente. Confirma a apresentação e a guarnição na ficha da casa.','Variação de assinatura do Preguiça Café & Cocktails sobre a família Mule, com gin e pepino. A história própria desta versão deve ser confirmada pela Gerência.'),
  ('Tequila Sunrise','Enche um copo alto com gelo e junta a tequila e o sumo de laranja. Verte a grenadine lentamente no final, para que assente e forme o efeito de cor. Não mexas depois.','A versão moderna ganhou popularidade na Califórnia durante a década de 1970. Há versões anteriores com outros ingredientes, pelo que a história do nome inclui mais de uma receita.'),
  ('Unicórnio (sem álcool)','A base e o sabor não estão especificados na ficha. Confirmar com a Gerência quais os ingredientes e a montagem antes de preparar.','Bebida de assinatura sem álcool do Preguiça Café & Cocktails. A composição e história específicas devem ser confirmadas pela Gerência.'),
  ('Virgin Blue Lagoon','Coloca gelo num copo alto. Junta o xarope/curaçao azul sem álcool e a lima, completa com Sprite e mexe suavemente. Confirma o produto azul usado na ficha da casa.','Adaptação sem álcool da família Blue Lagoon. A versão servida depende do xarope azul aprovado pela casa.'),
  ('Virgin Hurricane','Junta os sumos de laranja e ananás e a polpa de maracujá num shaker com gelo. Agita, verte para um copo com gelo fresco e serve.','Adaptação sem álcool inspirada no Hurricane associado a Nova Orleães. Esta versão substitui o rum por fruta e sumos.'),
  ('Virgin Mojito','Coloca a lima e o açúcar no copo e macera. Junta hortelã, pressionando-a ligeiramente. Enche com gelo, completa com ginger ale e mexe suavemente.','Adaptação sem álcool do Mojito cubano. Mantém a combinação de lima, açúcar e hortelã e substitui o rum por uma bebida sem álcool.'),
  ('Virgin Piña Colada','Junta o sumo de ananás e o coco no liquidificador com gelo picado. Tritura até ficar cremoso e serve de imediato.','Adaptação sem álcool da Piña Colada ligada a Porto Rico; conserva a combinação tropical de ananás e coco.')
) as source(name, method, history)
where recipe.name = source.name;
